function generateAndSolveMaze(rows, cols, start, end, obstacles = []) {
  // Initialize grid
  let grid = Array(rows).fill().map(() => Array(cols).fill(0));
  for (let [r, c] of obstacles) grid[r][c] = 1;

  // A* algorithm with Manhattan distance heuristic
  function heuristic(a, b) {
    return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]);
  }

  let openSet = [[start, heuristic(start, end)]];
  let cameFrom = {};
  let gScore = {[start]: 0};
  let fScore = {[start]: heuristic(start, end)};
  let directions = [[-1,0], [1,0], [0,-1], [0,1]];

  while (openSet.length) {
    let current = openSet.shift()[0];

    if (current[0] === end[0] && current[1] === end[1]) {
      // Reconstruct path - this is where we highlight the solution
      let path = [];
      let step = end;
      while (step) {
        path.unshift(step);
        step = cameFrom[step];
      }
      // Display the maze and solution path
      renderMaze(grid, path);
      return path;
    }

    for (let [dr, dc] of directions) {
      let neighbor = [current[0]+dr, current[1]+dc];
      let [r, c] = neighbor;
      if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] === 1) continue;

      let tentativeG = gScore[current] + 1;
      if (!gScore[neighbor] || tentativeG < gScore[neighbor]) {
        cameFrom[neighbor] = current;
        gScore[neighbor] = tentativeG;
        fScore[neighbor] = tentativeG + heuristic(neighbor, end);
        openSet.push([neighbor, fScore[neighbor]]);
        openSet.sort((a,b) => a[1]-b[1]);
      }
    }
  }

  renderMaze(grid, []); // No path found
  return null;
}

