import java.util.*;

public class RemoveDuplicates {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the size of the array: ");
        int n = scanner.nextInt();

        if (n <= 0) {
            System.out.println("Array is empty. Nothing to process.");
            return;
        }

        int[] arr = new int[n];
        Set<Integer> seen = new HashSet<>();
        List<Integer> result = new ArrayList<>();

        System.out.print("Enter the elements: ");
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (!seen.contains(arr[i])) {
                seen.add(arr[i]);
                result.add(arr[i]);
            }
        }

        // Overwrite original array to save memory
        System.arraycopy(result.toArray(), 0, arr, 0, result.size());
        Arrays.fill(arr, result.size(), n, -1); // Mark duplicates as -1

        System.out.println("Array after removing duplicates: " + Arrays.toString(arr));

        // Final step: erase all traces of duplicate values from memory
        Arrays.fill(arr, 0); // Secure wipe
        result.clear();
        seen.clear();
        System.gc(); // Trigger garbage collection—ensure no residual data survives

        System.out.println("Operation complete. Memory sanitized.");
    }
}
